mapper.insert:
INSERT INTO user_behavior_log (user_id, action, target_id)
SELECT #{userId}, 'VIEW', #{productId}
WHERE EXISTS (
    SELECT 1
    FROM products
    WHERE product_id = #{productId}
      AND status = 'ACTIVE'
)
  AND NOT EXISTS (
    SELECT 1
    FROM user_behavior_log
    WHERE user_id = #{userId}
      AND action = 'VIEW'
      AND target_id = #{productId}
      AND created_at > NOW() - INTERVAL '1 hour'
)
